import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十二卦 益 風雷益 巽上震下","description":"周易 - 第四十二卦 益 風雷益 巽上震下","frontmatter":{"title":"第四十二卦 益 風雷益 巽上震下","description":"周易 - 第四十二卦 益 風雷益 巽上震下"},"headers":[],"relativePath":"classics/zhouyi/043.md","filePath":"classics/zhouyi/043.md"}'),l={name:"classics/zhouyi/043.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="益" tabindex="-1">益 <a class="header-anchor" href="#益" aria-label="Permalink to “益”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利有攸往，利涉大川。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>益，損上益下，民說無疆，自上下下，其道大光。利有攸往，中正有慶。利涉大川，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>風雷，益；君子以見善則遷，有過則改。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>利用為大作，元吉，無咎。象 曰：元吉無咎，下不厚事也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>或益之，十朋之龜弗克違，永貞吉。王用享於帝，吉。象曰：或益之，自外來也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>益之用凶事，無咎。有孚中行，告公用圭。象曰：益用凶事，固有之也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>中行，告公從。利用為依遷國。象曰：告公從，以益志也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>有孚惠心，勿問元吉。有孚惠我德。象曰：有孚惠心，勿問之矣。惠我德，大得志也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>莫益之，或擊之，立心勿恆，兇。象曰：莫益之，偏辭也。或擊之，自外來也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
